// guarde os dois argumentos em constantes e monte o painel aqui

exercises.solution:
// Estas duas linhas fazem o papel do comando: node painel.js 302 Centro
process.argv[2] = '302';
process.argv[3] = 'Centro';

const linha = process.argv[2];
const destino = process.argv[3];

console.log('Linha:', linha);
console.log('Destino:', destino);
console.log('Ônibus', linha, 'para', destino);
